package kr.go.nifs.fieldrecorder;
import android.test.AndroidTestCase;
import org.json.*;
public class ExtractionTest extends AndroidTestCase {
 private JSONObject parse(String text,String phase) throws Exception{return FisheryExtractor.extract(text,phase);}
 private JSONObject first(JSONObject r) throws Exception {return r.getJSONArray("catches").getJSONObject(0);}
 public void testNativeAndSinoNumbers(){String[] words={"한","두","스무","서른","쉰","열두","스물세","마흔일곱","십오","백이십삼","천이백삼십사","일만이천","사점오","1,234.5"};double[] numbers={1,2,20,30,50,12,23,47,15,123,1234,12000,4.5,1234.5};for(int i=0;i<words.length;i++)assertEquals(words[i],numbers[i],KoreanNumber.parse(words[i]),0.00001);assertNull(KoreanNumber.parse("시인"));assertNull(KoreanNumber.parse("일이"));}
 public void testStartCommonFields() throws Exception {JSONObject r=parse("통발을 걷기 시작합니다. 목표 어종은 꽃게입니다. 이번에 걷는 통발은 쉰 개이고, 작업 인원은 세 명입니다.","START");assertEquals("꽃게",r.getString("target_species"));assertEquals("회수",r.getString("work_type"));assertEquals(50,r.getInt("gear_quantity"));assertEquals("개",r.getString("gear_unit"));assertEquals(3,r.getInt("workers"));assertEquals(0,r.getJSONArray("catches").length());}
 public void testCountsWeightSeparate() throws Exception {JSONObject r=parse("꽃게 스무 마리, 직접 잰 무게는 사 킬로그램입니다. 다른 어종은 잡히지 않았고 특이사항은 없습니다.","END"),c=first(r);assertEquals(20,c.getInt("quantity"));assertEquals(4,c.getDouble("weight_kg"),0.001);assertEquals("마리",c.getString("unit"));assertEquals("CAUGHT",r.getString("outcome"));assertEquals("EXPLICIT_NONE",r.getString("notes_state"));}
 public void testTargetNoneOtherCaught() throws Exception {JSONObject r=parse("목표로 한 참조기는 한 마리도 잡지 못했습니다. 대신 꽃게 세 마리를 잡았습니다. 꽃게 무게는 아직 재지 않았습니다.","END");assertEquals("CAUGHT",r.getString("outcome"));JSONArray a=r.getJSONArray("catches");assertEquals(2,a.length());assertEquals(0,a.getJSONObject(0).getInt("quantity"));assertEquals(3,a.getJSONObject(1).getInt("quantity"));assertTrue(a.getJSONObject(1).isNull("weight_kg"));}
 public void testOnlyTargetNoneNotOverallNone() throws Exception {JSONObject r=parse("참조기는 한 마리도 잡지 못했습니다.","END");assertEquals("UNCONFIRMED",r.getString("outcome"));assertEquals(0,first(r).getInt("quantity"));}
 public void testExplicitOverallNone() throws Exception {JSONObject r=parse("통발 서른 개를 모두 확인하고 회수를 끝냈습니다. 꽃게를 포함해 어떤 어종도 한 마리도 잡히지 않았습니다.","END");assertEquals("NO_CATCH",r.getString("outcome"));}
 public void testUnknownSpeciesBoxesNotKg() throws Exception {JSONObject r=parse("두 상자 정도 나왔습니다.","END"),c=first(r);assertTrue(c.isNull("species"));assertEquals(2,c.getInt("quantity"));assertEquals("상자",c.getString("unit"));assertTrue(c.isNull("weight_kg"));assertTrue(c.getBoolean("approximate"));assertEquals("UNCONFIRMED",r.getString("outcome"));}
 public void testMultipleSpeciesAndGramConversion() throws Exception {JSONObject r=parse("고등어 열두 마리, 갈치 세 마리, 꽃게 오백 그램입니다.","END");JSONArray a=r.getJSONArray("catches");assertEquals(3,a.length());assertEquals(12,a.getJSONObject(0).getInt("quantity"));assertEquals(3,a.getJSONObject(1).getInt("quantity"));assertEquals(0.5,a.getJSONObject(2).getDouble("weight_kg"),0.001);}
 public void testUnknownGearAndApproximateWorkers() throws Exception {JSONObject r=parse("장비는 열 개쯤 썼습니다. 오늘은 둘이 작업합니다.","START");assertEquals(10,r.getInt("gear_quantity"));assertTrue(r.getBoolean("gear_approximate"));assertEquals(2,r.getInt("workers"));assertTrue(r.isNull("target_species"));}
 public void testRangeNotEndpoint() throws Exception {JSONObject c=first(parse("꽃게 10에서 15마리 정도입니다.","END"));assertTrue(c.isNull("quantity"));}
 public void testCorrectionNeedsReview() throws Exception {JSONObject c=first(parse("꽃게 열 마리 아니 열두 마리입니다.","END"));assertTrue(c.isNull("quantity"));}
 public void testRepeatedConflictingCountsNeverSum() throws Exception {JSONObject c=first(parse("꽃게 세 마리입니다. 꽃게 네 마리입니다. 꽃게 다섯 마리입니다.","END"));assertTrue(c.isNull("quantity"));assertEquals("UNCONFIRMED",c.getString("outcome"));}
 public void testNoFishingNotZeroCatch() throws Exception {JSONObject r=parse("오늘은 조업을 하지 않았습니다.","END");assertEquals("NOT_FISHED",r.getString("outcome"));assertEquals(0,r.getJSONArray("catches").length());}
 public void testContradictionNotNoCatch() throws Exception {JSONObject r=parse("꽃게 세 마리입니다. 어떤 어종도 한 마리도 잡히지 않았습니다.","END");assertEquals("UNCONFIRMED",r.getString("outcome"));}
 public void testUnmentionedRemainsNull() throws Exception {JSONObject r=parse("조업을 마쳤습니다.","END");assertTrue(r.isNull("workers"));assertEquals(0,r.getJSONArray("catches").length());assertEquals("UNCONFIRMED",r.getString("outcome"));}
 public void testNoteOptionalAndUncertainCauseRetained() throws Exception {String text="바람이 강해졌습니다. 물때 때문인 것 같지만 확실하지 않습니다.";JSONObject r=parse(text,"NOTE");assertEquals(text,r.getString("notes_text"));assertEquals(0,r.getJSONArray("catches").length());}
 public void testArabicNoSpaceAndDecimal() throws Exception {JSONObject r=parse("고등어12마리, 무게는2.5kg입니다.","END");assertEquals(12,first(r).getInt("quantity"));assertEquals(2.5,first(r).getDouble("weight_kg"),0.001);}
 public void testSpeciesNotHallucinatedFromMisspelling() throws Exception {JSONObject r=parse("목표 어종은 꿋게입니다. 통발은 시인계입니다.","START");assertTrue(r.isNull("target_species"));assertTrue(r.isNull("gear_quantity"));assertTrue(r.getJSONArray("warnings").length()>0);}
 public void testVagueNumberDoesNotBecomeTen() throws Exception {JSONObject r=parse("꽃게 수십 마리입니다.","END");assertEquals("UNCONFIRMED",r.getString("outcome"));assertEquals(0,r.getJSONArray("catches").length());}
 public void testNegativeNumberNotPositive() throws Exception {JSONObject r=parse("꽃게 -3마리입니다.","END");assertEquals("UNCONFIRMED",r.getString("outcome"));assertEquals(0,r.getJSONArray("catches").length());}
 public void testHyphenRangeNotEndpoint() throws Exception {assertTrue(first(parse("꽃게 10-15마리입니다.","END")).isNull("quantity"));}
 public void testUnknownCompoundSpeciesNotShorterKnownName() throws Exception {JSONObject c=first(parse("학꽁치 세 마리입니다.","END"));assertTrue(c.isNull("species"));assertEquals(3,c.getInt("quantity"));}
 public void testSimpleNamedAbsence() throws Exception {JSONObject r=parse("참조기는 없습니다. 꽃게 세 마리입니다.","END");assertEquals("CAUGHT",r.getString("outcome"));assertEquals(0,first(r).getInt("quantity"));}
 public void testHomophoneNumberIsCandidateOnly() throws Exception {JSONObject c=first(parse("멸치 새 상자를 잡았습니다.","END"));assertTrue(c.isNull("quantity"));assertEquals(3,c.getInt("quantity_candidate"));assertEquals("상자",c.getString("unit"));assertEquals("UNCONFIRMED",c.getString("outcome"));}
 public void testHomophoneCrewIsCandidateOnly() throws Exception {JSONObject r=parse("작업 인원은 내 명입니다.","START");assertTrue(r.isNull("workers"));assertEquals(4,r.getInt("workers_candidate"));}
 public void testSimpleOverallAbsence() throws Exception {assertEquals("NO_CATCH",parse("어획은 없습니다.","END").getString("outcome"));assertEquals("NO_CATCH",parse("전체 무어획입니다.","END").getString("outcome"));}
 public void testNamedYieldAbsenceNotOverall() throws Exception {JSONObject r=parse("참조기 어획량은 없습니다.","END");assertEquals("UNCONFIRMED",r.getString("outcome"));assertEquals(0,first(r).getInt("quantity"));}
 public void testGearNounDoesNotConsumeSpacedNativeNumber() throws Exception {JSONObject r=parse("그물 열두 폭을 걷고 작업 인원은 네 명입니다.","START");assertEquals(12,r.getInt("gear_quantity"));assertEquals("폭",r.getString("gear_unit"));assertEquals(4,r.getInt("workers"));}
 public void testSpacedNativeAndDecimalNumbers() throws Exception {JSONObject r=parse("고등어 스물 일곱 마리 무게는 이 점 오 킬로그램입니다.","END");assertEquals(27,first(r).getInt("quantity"));assertEquals(2.5,first(r).getDouble("weight_kg"),0.001);}
}
